---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Scheduled runs: Tasks the agent runs on a schedule, with their last result and a switch.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change scheduled-runs.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './scheduled-runs.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="scheduled-runs" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="shx panel" data-reveal="flat">
  <div class="shx-h"><span class="shx-hi" aria-hidden="true"><svg class="i xs"><use href="#i-clock"/></svg></span><div><b>Scheduled runs</b></div></div>
  <div class="shx-list" role="list" aria-label="Schedules"></div>
  <div class="shx-ft"><button class="shx-add" data-pop=".shx-pop" aria-haspopup="dialog" aria-expanded="false"><svg class="i xs"><use href="#i-plus"/></svg>New schedule</button></div>
  <div class="pop shx-pop" role="dialog" aria-label="New schedule"><form class="shx-f">
    <h4>New schedule</h4>
    <input class="shx-in" placeholder="What should the agent do?" aria-label="What should the agent do?" spellcheck="false" autocomplete="off">
    <div class="seg2 shx-rep" role="group" aria-label="Repeat"><button type="button" aria-pressed="true" data-v="day">Every day</button><button type="button" aria-pressed="false" data-v="mon">Every Monday</button><button type="button" aria-pressed="false" data-v="custom">Custom</button></div>
    <div class="shx-days" role="group" aria-label="Days" hidden></div>
    <div class="shx-ff"><span class="muted shx-sum"></span><button class="pill accent sm shx-mk" type="submit" disabled>Create</button></div>
  </form></div>
</div>
  </Fragment></div>
</div>
<script>
  import './scheduled-runs.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Scheduled runs ---------- */
/* recurring agent tasks: the schedule in words, when it runs next and how its last run went, with Run now and an on/off
   switch. The card sits on two columns (owner, 18 Nov), its content 16px from every edge: the head's neutral mark in a 28px
   column with each run's mark under it, and the title and each run's words 12px after it; each run's mark, its three lines
   and its controls share one centre line, and the switches end on the content's right edge. A row is not a button, so it has
   no hover fill. The last line is the result, led by its mark (beside it, never over the run's own): a green tick when it
   passed, a red sign and the reason when it failed, with the fix under it, and a turning ring with words that shimmer while it
   runs. A paused one dims and says so. A run's mark is its tool's logo on a white tile, or its icon on a vivid tile of its
   colour (white or the colour's own ink on it). The card grows and shrinks with its rows (grow()) */
.shx{padding:var(--dm-s-4);display:flex;flex-direction:column}
.shx.growing:has(.pop.open){overflow:visible}
.shx-h{display:flex;align-items:center;gap:var(--dm-s-3);padding-bottom:var(--dm-s-2)}
.shx-hi{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));color:var(--dm-fg2);background:var(--dm-chip)}
.shx-h>div{flex:1;display:flex;flex-direction:column;min-width:0}
.shx-h b{font-weight:500;font-size:14px;line-height:20px}
.shx-st{font-size:12px;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.shx-list{display:flex;flex-direction:column}
.shx-r{display:grid;grid-template-columns:28px minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);padding:var(--dm-s-2) 0;font-size:13px}
.shx-r .ic{width:28px;height:28px;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;grid-row:1/4;align-self:center;transition:opacity var(--dm-t-fast) var(--dm-ease)}
.shx-r .ic.brandic{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-fg)}
.shx-r .ic .brand{width:15px;height:15px}
/* the name, the schedule and the result take the words' column; Run now and the switch sit beside all three */
.shx-r .t{display:contents}
.shx-r :is(.nm,.d,.res){grid-column:2;transition:color var(--dm-t-fast) var(--dm-ease)}
.shx-r .nm{line-height:20px}
/* a paused one dims: its tile fades, and its name and result step down to muted, so the text stays readable */
.shx-r.off .ic{opacity:.5}.shx-r.off :is(.nm,.res .i){color:var(--dm-muted)}
.shx-r .nm,.shx-r .d{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.shx-r .d{font-size:12px;line-height:18px;color:var(--dm-muted)}
.shx-r .res{display:flex;align-items:center;gap:5px;min-width:0;height:18px;font-size:12px;color:var(--dm-muted)}
.shx-r .res>span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.shx-r .res .shim{font-size:inherit}
.shx-r .res .i{flex:none;color:var(--dm-ok-mark)}
.shx-r .res .spin{width:11px;height:11px;margin:0 .5px;color:var(--dm-accent-mark,var(--dm-accent))}
.shx-r[data-st="bad"] .res{color:var(--dm-bad)}
/* why it failed is never cut short: on a narrow card it wraps, its sign on the first line */
.shx-r[data-st="bad"] .res{height:auto;min-height:18px;align-items:flex-start;line-height:18px}
.shx-r[data-st="bad"] .res .i{margin-top:3px}
.shx-r[data-st="bad"] .res>span{white-space:normal;text-wrap:pretty}
.shx-r[data-st="bad"] .res .i{color:var(--dm-bad-mark)}
.shx-act{grid-column:3;grid-row:1/4;align-self:center;display:flex;align-items:center;gap:var(--dm-s-2)}
.shx-run{width:28px;height:28px}
.shx-run:disabled{opacity:1;cursor:not-allowed;background:none;color:var(--dm-dis);transform:none}
.shx-r .shx-fx{grid-column:2/-1;grid-row:4}
.shx-fx>div{overflow-clip-margin:0px}
.shx-fx>div>div{display:flex;flex-wrap:wrap;gap:6px;padding-top:var(--dm-s-2)}
.shx-fx .pill .spin{width:11px;height:11px}
/* New schedule: its + centred in the marks' column and its words on the title's; the hover box starts on the content's edge */
.shx-add{display:flex;align-items:center;gap:var(--dm-s-3);align-self:flex-start;height:32px;margin-top:var(--dm-s-1);padding:0 var(--dm-s-3) 0 0;font-size:13px;color:var(--dm-fg2);border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
.shx-add>.i{width:28px;padding:0 8px;box-sizing:border-box}
.shx-add[aria-expanded="true"]{color:var(--dm-fg);background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.shx-add:hover{color:var(--dm-fg);background:var(--dm-row)}}
.shx-pop{width:272px;padding:var(--dm-s-3)}
.shx-f{display:flex;flex-direction:column;gap:var(--dm-s-2)}
.shx-f h4{margin:0 0 2px;font-size:13px;font-weight:500}
.shx-in{width:100%;height:32px;border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);padding:0 10px;font:inherit;font-size:13px;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.shx-in{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.shx-in::placeholder{color:var(--dm-muted)}
.shx-in:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.shx-rep{display:flex}
.shx-rep button{flex:1 1 auto;padding:0 var(--dm-s-2);white-space:nowrap}
.shx-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:var(--dm-s-1)}
.shx-days button{height:28px;border-radius:var(--dm-r-sm);background:var(--dm-chip);font-size:12px;color:var(--dm-fg2);transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.shx-days button:hover{background:var(--dm-hover);color:var(--dm-fg)}}
.shx-days button[aria-pressed="true"]{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.shx-ff{display:flex;align-items:center;gap:var(--dm-s-2);padding-top:2px}
.shx-sum{flex:1;min-width:0;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.shx :is(.ib,.pill,.shx-days button):active,:root[data-style="clean"] .shx .ib:active,:root [data-style="clean"] .shx .ib:active,:root [data-style="clean"].shx .ib:active{transform:none}
/* Clean (owner, 17 and 18 Nov): the head an off-white strip with a hairline under it; the runs' marks one neutral grey with
   a hairline (their logos keep their own colours); New schedule a flat secondary button on an off-white foot strip, 8px from
   the card's edges; the content 16px in from each edge and 16px from each strip; the form's days are round chips, its fields
   10px corners, and it scales and fades from its button with the card's corners */
:root[data-style="clean"] .shx.panel,:root [data-style="clean"] .shx.panel,:root [data-style="clean"].shx.panel{padding:0}
:root[data-style="clean"] .shx-h,:root [data-style="clean"] .shx-h,:root [data-style="clean"].shx-h{min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .shx-hi,:root [data-style="clean"] .shx-hi,:root [data-style="clean"].shx-hi{background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-hair);border-radius:10px}
:root[data-style="clean"] .shx-list,:root [data-style="clean"] .shx-list,:root [data-style="clean"].shx-list{padding:var(--dm-s-2) var(--dm-s-4)}
:root[data-style="clean"] .shx-r .ic,:root [data-style="clean"] .shx-r .ic,:root [data-style="clean"].shx-r .ic,:root[data-style="clean"] .shx-r .ic.brandic,:root [data-style="clean"] .shx-r .ic.brandic,:root [data-style="clean"].shx-r .ic.brandic{background:var(--dm-surface)!important;color:var(--dm-fg2)!important;box-shadow:inset 0 0 0 1px var(--dm-hair);border-radius:10px}
:root[data-style="clean"] .shx-r .res .i,:root [data-style="clean"] .shx-r .res .i,:root [data-style="clean"].shx-r .res .i{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}
:root[data-style="clean"] .shx-r[data-st="bad"] .res .i,:root [data-style="clean"] .shx-r[data-st="bad"] .res .i,:root [data-style="clean"].shx-r[data-st="bad"] .res .i{color:var(--dm-bad-mark)}
:root[data-style="clean"] .shx-r.off .res .i,:root [data-style="clean"] .shx-r.off .res .i,:root [data-style="clean"].shx-r.off .res .i{color:var(--dm-muted)}
:root[data-style="clean"] .shx-run,:root [data-style="clean"] .shx-run,:root [data-style="clean"].shx-run{transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .shx-ft,:root [data-style="clean"] .shx-ft,:root [data-style="clean"].shx-ft{padding:var(--dm-strip-y) var(--dm-s-4);background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .shx-add,:root [data-style="clean"] .shx-add,:root [data-style="clean"].shx-add{gap:6px;height:28px;margin:0;padding:0 12px 0 10px;border-radius:var(--dm-r-pill);font-weight:500;color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth);transition:box-shadow var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .shx-add>.i,:root [data-style="clean"] .shx-add>.i,:root [data-style="clean"].shx-add>.i{width:12px;padding:0}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] :is(.shx-add:hover,.shx-add[aria-expanded="true"]),:root [data-style="clean"] :is(.shx-add:hover,.shx-add[aria-expanded="true"]),:root [data-style="clean"]:is(.shx-add:hover,.shx-add[aria-expanded="true"]){background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .shx-add:active,:root [data-style="clean"] .shx-add:active,:root [data-style="clean"].shx-add:active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .shx-pop,:root [data-style="clean"] .shx-pop,:root [data-style="clean"].shx-pop{width:288px;padding:var(--dm-s-4);border-radius:var(--dm-r-card)}
:root[data-style="clean"] .shx-days button,:root [data-style="clean"] .shx-days button,:root [data-style="clean"].shx-days button{border-radius:var(--dm-r-pill);transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, BRAND, DM, I, REDUCE, closePops, enter, grow, html, placePop, popRoom, seg, stagger, swap } from '../core/core.js';
DM.def('scheduled-runs', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{plus}', I('plus','xs')).replace('{clock}', I('clock','xs'));
  // in this preview it is Saturday afternoon, so Monday at 9:00 is two days off, and every new schedule runs at 9:00. A run's
  // mark is its tool's logo, or its icon on a vivid tile of its colour
  const R = [
    { mark:'palette', col:'l', name:'Weekly design QA', when:'Mondays at 9:00', next:'Next in 2 days', on:true, res:'ok', ago:'5 days ago' },
    { mark:'@figma', name:'Sync tokens from Figma', when:'Every day at 8:00', next:'Next in 17h', on:true, res:'bad', why:'Figma token expired', fix:'Reconnect Figma' },
    { mark:'chart', col:'t', name:'Competitor price check', when:'Fridays at 17:00', next:'Next in 6 days', on:true, res:'ok', ago:'yesterday' }
  ];
  const root = $('.shx', r) || r, list = $('.shx-list', r), add = $('.shx-add', r), pop = $('.shx-pop', r), form = $('.shx-f', r);
  const inp = $('.shx-in', r), days = $('.shx-days', r), sum = $('.shx-sum', r), mk = $('.shx-mk', r);
  function row(x){
    const ic = x.mark[0] === '@' ? `<span class="ic brandic" aria-hidden="true">${BRAND[x.mark.slice(1)]}</span>` : `<span class="ic" style="background:var(--dm-av-${x.col});color:var(--dm-av-${x.col}-ink)" aria-hidden="true">${I(x.mark,'xs')}</span>`;
    x.el = html(`<div class="shx-r" role="listitem">${ic}<span class="t"><span class="nm"></span><span class="d"></span><span class="res"></span></span><span class="shx-act"><button class="ib shx-run" data-tip="Run now">${I('play')}</button><button class="toggle" role="switch"></button></span><div class="shx-fx fold shut" inert><div><div><button class="pill accent sm shx-fix"></button></div></div></div></div>`);
    $('.nm', x.el).textContent = x.name; $('.shx-run', x.el).setAttribute('aria-label', 'Run ' + x.name + ' now'); $('.toggle', x.el).setAttribute('aria-label', x.name);
    $('.shx-run', x.el).onclick = () => run(x);
    $('.toggle', x.el).onclick = () => { x.on = !x.on; paint(x); };
    $('.shx-fix', x.el).onclick = () => fix(x);
    paint(x, true); return x.el;
  }
  // the result line, led by its mark: a tick when it passed, a sign when it failed, a turning ring while it runs (its words
  // shimmer, as every line of a process at work)
  function paint(x, now){
    const el = x.el, put = (e, t, h) => now ? (h ? e.innerHTML = t : e.textContent = t) : swap(e, t, h);
    el.classList.toggle('off', !x.on); el.dataset.st = x.run ? 'run' : x.res || 'none';
    const tg = $('.toggle', el); tg.setAttribute('aria-checked', x.on); tg.dataset.tip = x.on ? 'Pause' : 'Resume';
    put($('.d', el), x.when + ' · ' + (x.on ? x.next : 'Paused'));
    const res = document.createElement('span'); res.textContent = x.run ? 'Running now' : x.res === 'ok' ? 'Passed ' + x.ago : x.res === 'bad' ? 'Failed: ' + x.why : 'No runs yet';
    if (x.run) res.className = 'shim';
    put($('.res', el), (x.run ? '<span class="spin" aria-hidden="true"></span>' : x.res ? I(x.res === 'ok' ? 'ok' : 'alert', 'xs') : '') + res.outerHTML, true);
    $('.shx-run', el).disabled = !!x.run || !x.on;
    const fx = $('.shx-fx', el), on = x.res === 'bad' && !x.run, b = $('.shx-fix', el);
    if (on && !x.fixing){ b.textContent = x.fix; b.removeAttribute('aria-disabled'); }
    fx.classList.toggle('shut', !on); fx.inert = !on;
  }
  // Run now: the result's ring turns while it runs, then it passes
  function run(x){
    if (x.run) return; x.run = true; paint(x);
    c.later(3000, () => { x.run = false; x.res = 'ok'; x.ago = 'just now'; paint(x); });
  }
  // the fix for a failed run reconnects, then runs it again straight away. The button is as wide as its words and eases to
  // the new ones
  function fix(x){
    if (x.fixing) return; x.fixing = true; const b = $('.shx-fix', x.el), w0 = b.getBoundingClientRect().width;
    // it keeps its colour while it reconnects, and takes no second press
    b.setAttribute('aria-disabled', 'true'); b.innerHTML = '<span class="spin"></span>Reconnecting'; const w1 = b.getBoundingClientRect().width;
    const cs = getComputedStyle(b), t = cs.getPropertyValue('--dm-t').trim();
    if (!REDUCE && Math.abs(w1 - w0) > .5) b.animate([{ width:w0 + 'px' }, { width:w1 + 'px' }], { duration:(t.endsWith('ms') ? parseFloat(t) : parseFloat(t) * 1000) || 340, easing:cs.getPropertyValue('--dm-ease').trim() || 'ease' });
    c.later(900, () => { x.fixing = false; run(x); });
  }
  // the head is the title alone: no count that repeats what the rows say (the owner's notes on batch 2)
  R.forEach(x => list.appendChild(row(x))); stagger([...list.children], 50);
  // New schedule: a task in words and how often. Custom picks the days; the line under it says when the first run is
  const DAY = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'], FULL = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
  days.innerHTML = DAY.map((d, i) => `<button type="button" aria-pressed="${i === 0 || i === 2 || i === 4}" aria-label="${FULL[i]}">${d[0]}</button>`).join('');
  let rep = 'day';
  const picked = () => rep === 'day' ? [0, 1, 2, 3, 4, 5, 6] : rep === 'mon' ? [0] : $$('button', days).map((b, i) => b.getAttribute('aria-pressed') === 'true' ? i : -1).filter(i => i >= 0);
  const when = ds => ds.length === 7 ? 'Every day at 9:00' : ds.join() === '0,1,2,3,4' ? 'Weekdays at 9:00' : ds.length === 1 ? FULL[ds[0]] + 's at 9:00' : ds.map(d => DAY[d]).join(', ') + ' at 9:00';
  // today is Saturday (5) after 9:00, so tomorrow's run is 18 hours off and the rest whole days
  const next = ds => { const n = Math.min(...ds.map(d => (d - 5 + 7) % 7 || 7)); return n === 1 ? 'Next in 18h' : `Next in ${n} days`; };
  function form1(){ const ds = picked(); sum.textContent = ds.length ? next(ds).replace('Next', 'First run') : 'Pick at least one day'; mk.disabled = !inp.value.trim() || !ds.length; }
  // a menu opens over the card from its button: down when it fits below, up when it doesn't and fits above or has more room
  // there (as placePop), within the stage's room, so it never spills over the card's caption under the stage (as Artifact
  // card's version menu). The side is set on the button just before the menu is placed
  const side = (btn, pop) => { const room = popRoom(btn), st = btn.closest('.stage-inner') || btn.closest('.stage');
    if (st){ const sr = st.getBoundingClientRect(), cs = getComputedStyle(st); room.top = Math.max(room.top, sr.top + parseFloat(cs.paddingTop)); room.bottom = Math.min(room.bottom, sr.bottom - parseFloat(cs.paddingBottom)); }
    const br = btn.getBoundingClientRect(), need = pop.offsetHeight + 12, below = room.bottom - br.bottom, above = br.top - room.top;
    btn.dataset.popPos = below < need && (above >= need || above > below) ? 'up' : 'down'; };
  // the form keeps the side it opened on: one that opened upwards grows upwards, held by its bottom edge
  const replace = () => { if (!(pop.style.getPropertyValue('--dm-origin') || '').startsWith('bottom')) side(add, pop); placePop(add, pop); };
  seg($('.shx-rep', r), v => { rep = v; days.hidden = v !== 'custom'; form1(); if (pop.classList.contains('open')) replace(); });
  $$('button', days).forEach(b => b.onclick = () => { b.setAttribute('aria-pressed', b.getAttribute('aria-pressed') !== 'true'); form1(); });
  inp.oninput = form1; form1();
  c.on(add, 'click', e => { if (pop.classList.contains('open')) return; side(add, pop); if (e.isTrusted) c.later(0, () => inp.focus({ preventScroll:true })); });
  c.on(form, 'submit', e => {
    e.preventDefault(); const ds = picked(); if (!inp.value.trim() || !ds.length) return;
    const x = { mark:'clock', col:'b', name:inp.value.trim(), when:when(ds), next:next(ds), on:true, res:null };
    R.push(x); list.appendChild(row(x)); enter(x.el); closePops(); inp.value = ''; form1();
  });
  // the card grows with its rows, and eases as a fix folds open or shut (owner, 17 Nov: no room kept for a later state)
  c.offs.push(grow(root));
  // the preview's story: run the design QA now and watch it pass, reconnect Figma so the token sync passes again, then
  // pause the price check
  c.story(async s => {
    const [qa, fig, price] = R;
    await s.beat(3);
    await s.point($('.shx-run', qa.el)); await s.beat(1);
    await s.tap($('.shx-run', qa.el)); s.away();
    await s.until(() => !qa.run && qa.ago === 'just now'); await s.beat(2);
    await s.tap($('.shx-fix', fig.el)); s.away();
    await s.until(() => !fig.run && fig.res === 'ok'); await s.beat(2);
    await s.tap($('.toggle', price.el)); s.away(); await s.beat(3);
  });
});
